import { ARTICLES, ARTICLE_ALIASES } from '../public/knowledge/content.js';

// Generated from the validated complete articles. Never maintain a second list.
export function knowledgeCatalogueSource() {
  const fields = [
    'id',
    'title',
    'summary',
    'aliases',
    'topicGroup',
    'categoryId',
    'capabilityIds',
    'relatedIds',
  ];
  const articles = ARTICLES.map((article) =>
    Object.fromEntries(fields.map((key) => [key, article[key]])),
  );
  return (
    '// Generated by scripts/build-knowledge-catalogue.mjs; edit knowledge/articles instead.\n' +
    "const freeze = value => { if (value && typeof value === 'object') { Object.values(value).forEach(freeze); Object.freeze(value); } return value; };\n" +
    'export const ARTICLES = freeze(' +
    JSON.stringify(articles) +
    ');\n' +
    'export const ARTICLE_ALIASES = freeze(' +
    JSON.stringify(ARTICLE_ALIASES) +
    ');\n'
  );
}
